const e = items[0].json;
const exec = e.execution || {};
const err = e.execution?.error || e.error || {};
const wf = e.workflow || {};

const lines = [
  `🚨 *n8n workflow failed*`,
  ``,
  `*Workflow:* ${wf.name || 'unknown'} (\`${wf.id || '?'}\`)`,
  `*Failed node:* \`${err.node?.name || '?'}\` (${err.node?.type || '?'})`,
  `*Error:* ${err.message || String(err) || 'no message'}`,
  ``,
  `*Execution:* ${exec.url || `${process.env.N8N_HOST || 'n8n'}/execution/${exec.id || '?'}`}`,
  `*Mode:* ${exec.mode || 'unknown'}`,
  `*Time:* ${e.execution?.startedAt || $now.toISO()}`,
];

return [{
  json: {
    text: lines.join('\n'),
    chat_id: $env.TELEGRAM_ALERT_CHAT_ID,
    parse_mode: 'Markdown'
  }
}];
